final class DiscoverSheet {
 static {String[][] words={{"Full page ›","الصفحة الكاملة ›"},{"Title preview","معاينة العنوان"},{"Close preview","إغلاق المعاينة"},{"Swipe down to close","اسحب للأسفل للإغلاق"},{"Loading details…","جارٍ تحميل التفاصيل…"},{"No synopsis available.","لا يتوفر ملخص."},{"Add to My List","إضافة إلى قائمتي"},{"Add to library","إضافة إلى المكتبة"},{"Log","تسجيل المشاهدة"},{"Details unavailable. Open the full page to retry.","التفاصيل غير متاحة. افتح الصفحة الكاملة للمحاولة مجددًا."}};for(String[] p:words)Loc.AR.put(p[0],p[1]);}
 final Activity a;final Dialog dialog;final LinearLayout content;final DiscoveryClient client;JSONObject title;int revision=0;boolean closed=false;
 static void show(Activity a,JSONObject seed,View source){new DiscoverSheet(a,DataStore.copy(seed),source);}
 DiscoverSheet(Activity activity,JSONObject seed,View source){a=activity;title=seed;client=new DiscoveryClient(a);Rect bounds=source==null?null:HomeLayout.bounds(source);dialog=new Dialog(a);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout sheet=new LinearLayout(a);sheet.setOrientation(LinearLayout.VERTICAL);sheet.setPadding(0,0,0,dp(20));sheet.setBackground(MainActivity.bg(MainActivity.PANEL,dp(22)));sheet.setClipToOutline(true);sheet.setTag("art-tint");View handle=new View(a);handle.setBackground(MainActivity.bg(0xff77716a,dp(3)));FrameLayout drag=new FrameLayout(a);drag.setContentDescription(Loc.t("Swipe down to close"));FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(dp(44),dp(4),Gravity.CENTER);drag.addView(handle,hp);sheet.addView(drag,new LinearLayout.LayoutParams(-1,dp(38)));float[] down={0};drag.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){down[0]=e.getRawY();return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){sheet.setTranslationY(Math.max(0,e.getRawY()-down[0]));return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){if(e.getActionMasked()==MotionEvent.ACTION_UP&&sheet.getTranslationY()>dp(88))dialog.dismiss();else if(Motion.enabled(sheet))sheet.animate().translationY(0).setDuration(180).start();else sheet.setTranslationY(0);return true;}return false;});ScrollView scroll=new ScrollView(a);content=new LinearLayout(a);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(22),0,dp(22),dp(12));scroll.addView(content);sheet.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(sheet);dialog.setOnDismissListener(d->{closed=true;revision++;});dialog.show();Window window=dialog.getWindow();window.setBackgroundDrawableResource(android.R.color.transparent);window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams wp=window.getAttributes();wp.width=-1;wp.height=(int)(a.getResources().getDisplayMetrics().heightPixels*.86);wp.gravity=Gravity.BOTTOM;wp.dimAmount=.64f;window.setAttributes(wp);sheet.setLayoutDirection(Loc.arabic?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);paint(false);HomeLayout.enter(sheet,bounds);load();}
 int dp(int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
 TextView text(String value,int size,int color){TextView v=new TextView(a);v.setText(Loc.t(value));v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(7),0,dp(7));return v;}
 TextView action(String value,Runnable run,boolean primary){TextView v=text(value,15,primary?MainActivity.BLACK:MainActivity.WHITE);v.setPadding(dp(16),dp(13),dp(16),dp(13));v.setGravity(Gravity.CENTER);v.setBackground(MainActivity.bg(primary?MainActivity.GOLD:0xff343132,dp(14)));v.setTypeface(null,Typeface.BOLD);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));v.setLayoutParams(lp);v.setOnClickListener(w->{dialog.dismiss();run.run();});Motion.card(v);return v;}
 void full(){a.startActivity(new Intent(a,DiscoverActivity.class).putExtra("title",title.toString()));}
 void paint(boolean loaded){int view=++revision;content.removeAllViews();String url=title.optString("background",title.optString("poster"));ImageView art=new ImageView(a);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(MainActivity.bg(Motion.placeholder(url),dp(14)));art.setClipToOutline(true);content.addView(art,new LinearLayout.LayoutParams(-1,dp(180)));NoirApp.data.images.execute(()->{try{android.graphics.Bitmap b=client.art(url);if(b!=null)Motion.remember(url,b);a.runOnUiThread(()->{if(!closed&&view==revision&&b!=null){Motion.loaded(art,b,url);HomeLayout.tint(art,url);}});}catch(Exception ignored){}});TextView name=text(title.optString("name"),28,MainActivity.WHITE);name.setTypeface(null,Typeface.BOLD);content.addView(name);List<String> facts=new ArrayList<>();for(String value:new String[]{title.optString("releaseInfo"),title.optString("runtime"),title.optString("imdbRating").isEmpty()?"":"★ "+title.optString("imdbRating")+" IMDb"})if(!value.isEmpty())facts.add(value);for(Object value:HomeLayout.jsonValues(title.optJSONArray("genres")))if(facts.size()<6)facts.add(Loc.t(String.valueOf(value)));content.addView(text(String.join(" · ",facts),12,MainActivity.GOLD));String description=title.optString("description");content.addView(text(description.isEmpty()?loaded?"No synopsis available.":"Loading details…":description,14,MainActivity.MUTED));boolean ready=loaded&&(title.optString("noirType").equals("movie")||DiscoveryClient.episodes(title).stream().anyMatch(DiscoveryClient::released));if(!PhoneExperience.trackerOnly(NoirApp.data)){TextView stream=action("Stream",()->perform("stream"),true);stream.setEnabled(ready);stream.setAlpha(ready?1:.45f);content.addView(stream);TextView download=action("Download to phone",()->perform("download"),false);download.setEnabled(ready);download.setAlpha(ready?1:.45f);content.addView(download);}TextView list=action("Add to My List",()->perform("list"),false);list.setEnabled(ready);content.addView(list);content.addView(action("Log",()->a.startActivity(new Intent(a,LogActivity.class).putExtra("imdb",title.optString("id")).putExtra("query",title.optString("name"))),false));TextView full=action("Full page ›",this::full,false);full.setTextColor(MainActivity.GOLD);content.addView(full);content.addView(action("Close preview",()->{},false));}
 void load(){NoirApp.data.network.execute(()->{try{JSONObject details=client.details(title);a.runOnUiThread(()->{if(!closed&&!a.isDestroyed()){title=details;paint(true);}});}catch(Exception e){a.runOnUiThread(()->{if(!closed&&!a.isDestroyed())content.addView(text("Details unavailable. Open the full page to retry.",13,MainActivity.MUTED));});}});}
 void perform(String kind){try{JSONObject selected=null,first=null;for(JSONObject value:PhoneSeasonPlan.discoverItems(title)){JSONObject saved=NoirApp.data.rememberPhoneItem(value);if(first==null)first=saved;if(selected==null&&(saved.optBoolean("movie")||DataStore.date(saved.optString("airsAt"))<=System.currentTimeMillis()))selected=saved;}if(first==null)return;if(kind.equals("list")){JSONObject op=NoirApp.data.operation(first.optString("id"),"list");DataStore.put(op,"value",true);NoirApp.data.queue(op);NoirApp.data.syncSoon();Toast.makeText(a,Loc.t("Saved to My List"),Toast.LENGTH_SHORT).show();}else if(selected!=null){if(kind.equals("stream"))PhoneStream.start(a,selected,false);else PhoneDownloadsActivity.open(a,selected,false);}}catch(Exception e){Toast.makeText(a,Loc.t("Details unavailable. Open the full page to retry."),Toast.LENGTH_LONG).show();}}
}
